function audit(page,label){const a={label,phase:'init',pageErrors:[],requests:[],console:[]};page.on('pageerror',e=>a.pageErrors.push({phase:a.phase,message:String(e.message||e),stack:String(e.stack||'')}));page.on('requestfailed',r=>a.requests.push({phase:a.phase,url:r.url(),error:String(r.failure()?.errorText||'')}));page.on('console',m=>{if(m.type()==='error')a.console.push({phase:a.phase,text:m.text(),location:m.location()})});return a}
function knownStartupPageError(e){if(!/^open:/.test(e.phase))return false;const s=(e.message||'')+'\n'+(e.stack||'');if(/Load failed/i.test(e.message||'')&&/coi-serviceworker\.js/i.test(e.stack||''))return true;return /shogi-side-test\/(?:dialogue21510\.js|hana21512\/(?:naoe|date|keiji)\.b64\.txt).*access control checks/i.test(s)&&/coi-serviceworker\.js/i.test(e.stack||'')}
function knownStartupConsole(e){if(!/^open:/.test(e.phase))return false;const t=e.text||'',u=e.location?.url||'';if(/Data URL decoding failed|favicon/i.test(t))return true;if(/coi-serviceworker\.js/i.test(u)&&(/save\/cloud patch inject failed|A ServiceWorker intercepted|COI fetch failed|^Error$/i.test(t)))return true;if(/v2\.15\.10 dialogue patch load failed TypeError: Load failed/i.test(t))return true;if(/hana images 2\.15\.12 TypeError: Load failed/i.test(t))return true;return false}
function assertClean(a,{conflict=false}={}){const badPage=a.pageErrors.filter(e=>!knownStartupPageError(e));const badReq=a.requests.filter(e=>!/NS_BINDING_ABORTED|Load request cancelled|ERR_ABORTED/i.test(e.error));const badConsole=a.console.filter(e=>{if(knownStartupConsole(e))return false;if(conflict&&/409|Conflict/i.test(e.text||''))return false;return true});assert.deepEqual(badPage,[]);assert.deepEqual(badReq,[]);assert.deepEqual(badConsole,[]);return {knownStartupPageErrors:a.pageErrors.length,knownAbortedRequests:a.requests.length,knownConsole:a.console.length}}
async function waitApp(p){await p.waitForFunction(()=>crossOriginIsolated&&document.querySelectorAll('#chars .ch').length===26&&window.AI_SHOGI_YANEURAOU_FUTURE?.strengthTune==='fullsearch-20260825'&&window.AI_SHOGI_SAVE?.version==='21530a'&&window.AI_SHOGI_CLOUD_SAVE?.version==='21531c'&&window.AI_SHOGI_DIALOGUE_AUDIT?.version==='2.15.10'&&window.AI_SHOGI_HANA_IMAGE_AUDIT?.ok===true&&document.getElementById('cloudSaveBtn')&&document.getElementById('cloudPullBtn'),null,{timeout:150000});await sleep(500)}
async function assertRecoveredAssets(p,{portraits=false}={}){const s=await p.evaluate(({HANA_INDICES})=>{const cards=[...document.querySelectorAll('#chars .ch')],counts=window.AI_SHOGI_DIALOGUE_AUDIT?.counts||{},names=Object.keys(counts);return {hana:window.AI_SHOGI_HANA_IMAGE_AUDIT,dialogue:{version:window.AI_SHOGI_DIALOGUE_AUDIT?.version,recentAvoid:window.AI_SHOGI_DIALOGUE_AUDIT?.recentAvoid,names,allMoods:names.length===8&&names.every(n=>Object.values(counts[n]||{}).length===9&&Object.values(counts[n]||{}).every(v=>Number(v)>0))},cards:HANA_INDICES.map(i=>{const c=cards[i],img=c?.querySelector('img');return {name:(c?.querySelector('.chName')?.textContent||img?.alt||'').trim(),src:String(img?.src||''),complete:!!img?.complete,w:img?.naturalWidth||0,h:img?.naturalHeight||0}})}},{HANA_INDICES});assert.equal(s.hana?.ok,true);assert.equal(s.hana?.version,'2.15.12');assert.deepEqual([...(s.hana?.loaded||[])].sort((a,b)=>a-b),[8,11,18]);assert.equal(s.dialogue.version,'2.15.10');assert.equal(s.dialogue.recentAvoid,4);assert.equal(s.dialogue.names.length,8);assert.equal(s.dialogue.allMoods,true);assert.deepEqual(s.cards.map(x=>x.name),HANA_NAMES);assert.ok(s.cards.every(x=>x.complete&&x.w>0&&x.h>0&&x.src.startsWith('data:image/webp;base64,')));if(portraits){for(const [n,i] of HANA_INDICES.entries()){await p.locator('#chars .ch').nth(i).click();await p.waitForTimeout(80);const q=await p.evaluate(()=>{const img=document.querySelector('#oppPortrait img');return {name:(document.getElementById('oppName')?.textContent||'').trim(),w:img?.naturalWidth||0,h:img?.naturalHeight||0,src:String(img?.src||'')}});assert.ok(q.name.includes(HANA_NAMES[n]));assert.ok(q.w>0&&q.h>0&&q.src.startsWith('data:image/webp;base64,'))}}return {hanaLoaded:[8,11,18],dialogueProfiles:8,hannaImagesHealthy:true}}
async function openApp(p,a,label,{portraits=false}={}){a.phase='open:'+label;await p.goto(`${BASE}/index.html?pr87finalv4=${encodeURIComponent(label)}-${RUN}-${Date.now()}`,{waitUntil:'domcontentloaded',timeout:120000});await waitApp(p);const recovery=await assertRecoveredAssets(p,{portraits});a.phase='ready:'+label;return recovery}
