for(const [name,type,userAgent,viewport,hashMB] of ENVS){const b=await type.launch({headless:true}),ctx=await b.newContext({userAgent,viewport}),p=await ctx.newPage(),a=audit(p,name);try{const recovery=await openApp(p,a,name,{portraits:name==='IPHONE_WEBKIT'});const base=await p.evaluate(()=>({coi:crossOriginIsolated,cards:document.querySelectorAll('#chars .ch').length,unique:new Set([...document.querySelectorAll('#chars .ch')].map(x=>(x.querySelector('.chName')?.textContent||x.querySelector('img')?.alt||'').trim())).size,future:{index:AI_SHOGI_YANEURAOU_FUTURE.index,rating:AI_SHOGI_YANEURAOU_FUTURE.rating,tune:AI_SHOGI_YANEURAOU_FUTURE.strengthTune},cloud:AI_SHOGI_CLOUD_SAVE.audit(),overflow:document.documentElement.scrollWidth>innerWidth+1}));assert.equal(base.coi,true);assert.equal(base.cards,26);assert.equal(base.unique,26);assert.deepEqual(base.future,{index:25,rating:3400,tune:'fullsearch-20260825'});assert.equal(base.cloud.backend,'supabase-edge-cas-v1');assert.deepEqual(base.cloud.buttons,{cloud:true,pull:true});assert.equal(base.overflow,false);a.phase='engine-search';const engine=await p.evaluate(async st=>{const x=AI_SHOGI_YANEURAOU_FUTURE,t=performance.now();await x.init();const r=await x.bestMove(st,{ms:300,multiPV:1,adaptive:false});return {ms:Math.round(performance.now()-t),status:x.status(),r,info:r?.info||{}}},initial());assert.equal(engine.status.ready,true);assert.equal(engine.status.worker,true);assert.equal(engine.info.hashMB,hashMB);assert.equal(engine.info.threads,1);assert.equal(engine.info.adaptive,false);assert.ok(engine.r?.move||engine.r?.resign||engine.r?.declareWin);a.phase='sound-persist';assert.equal(await p.evaluate(()=>{AI_SHOGI_PIECE_SOUND.setEnabled(false);return AI_SHOGI_PIECE_SOUND.enabled}),false);await p.reload({waitUntil:'domcontentloaded',timeout:120000});await waitApp(p);await assertRecoveredAssets(p);assert.equal(await p.evaluate(()=>AI_SHOGI_PIECE_SOUND.enabled),false);await p.evaluate(()=>AI_SHOGI_PIECE_SOUND.setEnabled(true));const played=await playFuture(p,a),ply=played.save.savedPly;assert.ok(ply>=2);assert.equal(played.save.currentPly,ply);assert.equal(played.data.ci,25);a.phase='local-reload';await p.reload({waitUntil:'domcontentloaded',timeout:120000});await waitApp(p);await assertRecoveredAssets(p);assert.equal((await p.evaluate(()=>AI_SHOGI_SAVE.audit())).savedPly,ply);assert.equal(await p.evaluate(()=>AI_SHOGI_SAVE.load()),true);const restored=await p.evaluate(()=>({a:AI_SHOGI_SAVE.audit(),opp:document.getElementById('oppName')?.textContent||''}));assert.equal(restored.a.currentPly,ply);assert.equal(restored.a.currentCharacter,25);assert.ok(restored.opp.includes('未来からやってきたみつき'));const known=assertClean(a);console.log('PR87_PUBLIC_FINAL_V4_ENV '+JSON.stringify({name,coi:true,cards:26,unique:26,hashMB,threads:1,backend:'supabase-edge-cas-v1',futureRealReply:true,soundPersist:true,savedPly:ply,reloadRestore:true,overflow:false,recovery,unexpectedPageErrors:[],unexpectedRequestFailures:[],unexpectedConsoleErrors:[],knownTransient:known}))}finally{await ctx.close();await b.close()}}

