const wb=await webkit.launch({headless:true}),cb=await chromium.launch({headless:true});const ic=await wb.newContext({userAgent:UA.iphone,viewport:{width:390,height:844}}),pc=await cb.newContext({userAgent:UA.chrome,viewport:{width:1440,height:900}});await seed(ic,`finalv4_iphone_${RUN}`);await seed(pc,`finalv4_pc_${RUN}`);const ip=await ic.newPage(),cp=await pc.newPage(),ia=audit(ip,'IPHONE_A'),ca=audit(cp,'PC_B');try{const recI=await openApp(ip,ia,'MIXED_IPHONE_A',{portraits:true});const original=(await playFuture(ip,ia)).save.savedPly;const code=crypto.randomBytes(24).toString('base64url');ia.phase='iphone-push';assert.equal(await ip.evaluate(c=>AI_SHOGI_CLOUD_SAVE.enableWithCode(c),code),true);await ip.waitForFunction(()=>{const m=AI_SHOGI_CLOUD_SAVE.meta();return m.revision>=1&&!m.pending},null,{timeout:20000});const aRev=await ip.evaluate(()=>AI_SHOGI_CLOUD_SAVE.meta().revision);const recC=await openApp(cp,ca,'MIXED_PC_B');ca.phase='pc-pull';assert.equal(await cp.evaluate(c=>AI_SHOGI_CLOUD_SAVE.enableWithCode(c),code),true);await cp.waitForFunction(p=>AI_SHOGI_SAVE?.audit().currentPly===p,original,{timeout:20000});await cp.waitForFunction(()=>!AI_SHOGI_CLOUD_SAVE.meta().pending,null,{timeout:20000});const pc0=await cp.evaluate(()=>({m:AI_SHOGI_CLOUD_SAVE.meta(),a:AI_SHOGI_SAVE.audit(),ci:AI_SHOGI_SAVE.data()?.ci}));assert.equal(pc0.a.currentPly,original);assert.equal(pc0.ci,25);ca.phase='pc-save';await cp.evaluate(()=>{const x=AI_SHOGI_SAVE.data();x.savedAt=Date.now()+1000;x.st.log=[...(x.st.log||[]),{cloudTest:'PC-B'}];localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(x));window.dispatchEvent(new Event('ai-shogi-local-save'))});await cp.waitForFunction(r=>{const m=AI_SHOGI_CLOUD_SAVE.meta();return m.revision>r&&!m.pending},pc0.m.revision,{timeout:20000});const pcRev=await cp.evaluate(()=>AI_SHOGI_CLOUD_SAVE.meta().revision);ia.phase='iphone-conflict';await ip.evaluate(()=>{const x=AI_SHOGI_SAVE.data();x.savedAt=Date.now()+2000;x.st.log=[...(x.st.log||[]),{cloudTest:'IPHONE-A-PENDING'}];localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(x));window.dispatchEvent(new Event('ai-shogi-local-save'))});await ip.waitForFunction(()=>{const m=AI_SHOGI_CLOUD_SAVE.meta();return m.pending&&m.lastError==='conflict'},null,{timeout:20000});const protectedPull=await ip.evaluate(()=>AI_SHOGI_CLOUD_SAVE.pull());assert.equal(protectedPull.localPending,true);assert.equal(await ip.evaluate(()=>JSON.parse(localStorage.getItem('aiShogiGameSaveV1')).st.log.at(-1).cloudTest),'IPHONE-A-PENDING');ia.phase='iphone-explicit-discard';ip.once('dialog',d=>d.accept());await ip.click('#cloudPullBtn');await ip.waitForFunction(()=>{const m=AI_SHOGI_CLOUD_SAVE.meta(),x=JSON.parse(localStorage.getItem('aiShogiGameSaveV1')||'null');return !m.pending&&x?.st?.log?.at(-1)?.cloudTest==='PC-B'},null,{timeout:20000});await sleep(1200);const fin=await ip.evaluate(()=>({m:AI_SHOGI_CLOUD_SAVE.meta(),x:JSON.parse(localStorage.getItem('aiShogiGameSaveV1'))}));assert.ok(fin.m.revision>=pcRev);assert.equal(fin.m.pending,false);assert.equal(fin.m.lastError,'');assert.equal(fin.x.st.log.at(-1).cloudTest,'PC-B');assert.equal(fin.x.ci,25);const knownI=assertClean(ia,{conflict:true}),knownC=assertClean(ca);console.log('PR87_PUBLIC_FINAL_V4_MIXED '+JSON.stringify({from:'iPhone WebKit',to:'desktop Chromium',back:'desktop Chromium -> iPhone WebKit',originalPly:original,iphoneInitialRevision:aRev,pcRevisionAfterSave:pcRev,iphoneFinalRevision:fin.m.revision,iphoneToPcRestore:true,conflictProtected:true,explicitDiscardRestorePcToIphone:true,pending:false,lastError:'',backend:'supabase-edge-cas-v1',iphoneRecovery:recI,pcRecovery:recC,knownIphoneTransient:knownI,knownPcTransient:knownC}))}finally{await ic.close();await pc.close();await wb.close();await cb.close()}
